import { Flex, Switch, Text } from '@gravity-ui/uikit';

interface AppProps {
  theme: 'light' | 'dark';
  onThemeChange: (theme: 'light' | 'dark') => void;
}

export function App({ theme, onThemeChange }: AppProps) {
  return (
    <Flex direction=\"column\" gap={3} spacing={{ p: 6 }}>
      <Text variant=\"header-1\">Theme switcher</Text>
      <Flex alignItems=\"center\" gap={3}>
        <Switch
          checked={theme === 'dark'}
          onUpdate={(checked) => onThemeChange(checked ? 'dark' : 'light')}
        >
          Dark theme
        </Switch>
        <Text variant=\"body-1\">Current theme: {theme}</Text>
      </Flex>
    </Flex>
  );
}
EOF
cat > src/main.tsx <<'EOF'
// Preconfigured Gravity UI setup is ALREADY wired here (both CSS imports + ThemeProvider).
import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React, { useState } from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider } from '@gravity-ui/uikit';

import { App } from './App';

const THEME_STORAGE_KEY = 'app-theme';
type Theme = 'light' | 'dark';

function getInitialTheme(): Theme {
  const savedTheme = window.localStorage.getItem(THEME_STORAGE_KEY);
  return savedTheme === 'dark' ? 'dark' : 'light';
}

function Root() {
  const [theme, setTheme] = useState<Theme>(getInitialTheme);

  const handleThemeChange = (nextTheme: Theme) => {
    setTheme(nextTheme);
    window.localStorage.setItem(THEME_STORAGE_KEY, nextTheme);
  };

  return (
    <ThemeProvider theme={theme}>
      <App theme={theme} onThemeChange={handleThemeChange} />
    </ThemeProvider>
  );
}

ReactDOM.createRoot(document.getElementById('root')"'!).render(
  <React.StrictMode>
    <Root />
  </React.StrictMode>,
);
EOF'
